def normalize_prescription_medicines_for_json_field(apps, schema_editor):
    """
    medicines was TextField; rows may hold plain text (e.g. "Paracetamol 500mg").
    PostgreSQL cannot cast that to jsonb. Rewrite every row to a JSON array string first.
    """
    Prescription = apps.get_model("consultations", "Prescription")

    def to_json_text(raw):
        if raw is None:
            return json.dumps([])
        if isinstance(raw, list):
            return json.dumps(raw)
        if isinstance(raw, dict):
            return json.dumps([raw])
        s = str(raw).strip()
        if not s:
            return json.dumps([])
        try:
            parsed = json.loads(s)
            if isinstance(parsed, list):
                return json.dumps(parsed)
            if isinstance(parsed, dict):
                return json.dumps([parsed])
            return json.dumps([{"name": str(parsed), "_legacy_wrapped": True}])
        except json.JSONDecodeError:
            return json.dumps([{"name": s, "_legacy_plaintext": True}])

    for p in Prescription.objects.all().only("id", "medicines"):
        new_text = to_json_text(p.medicines)
        Prescription.objects.filter(pk=p.pk).update(medicines=new_text)


